export function getCategoryColor(category: string): string {
  switch (category) {
    case "Bail": return "#D97706"
    case "Criminal": return "#DC2626"
    case "Civil": return "#2563EB"
    case "Family": return "#059669"
    case "Constitutional": return "#7C3AED"
    case "Consumer": return "#0891B2"
    case "Procedural": return "#6B7280"
    case "Conveyancing": return "#B45309"
    case "Tax": return "#CA8A04"
    case "Commercial": return "#4F46E5"
    case "Estates": return "#9333EA"
    case "Labour": return "#EA580C"
    case "Arbitration": return "#0D9488"
    case "Insolvency": return "#BE123C"
    case "IP": return "#0284C7"
    case "Regulatory": return "#65A30D"
    case "NRI": return "#C026D3"
    case "International": return "#0369A1"
    default: return "#7C3AED"
  }
}
